function relinkAndRemove(nodes, id) {
  const node = nodes[id];
  if (!node || node.type !== "dialogue") return;

  for (const candidate of Object.values(nodes)) {
    if (candidate.next === id) candidate.next = node.next;
    if (candidate.then === id) candidate.then = node.next;
    if (candidate.else === id) candidate.else = node.next;
    if (Array.isArray(candidate.options)) {
      for (const option of candidate.options) {
        if (option.next === id) option.next = node.next;
      }
    }
  }

  delete nodes[id];
}

export function plainLanguage(nodes) {
  for (const [id, text] of Object.entries(NODE_TEXT_OVERRIDES)) {
    const node = nodes[id];
    if (node) node.text = text;
  }

  for (const [id, prompt] of Object.entries(NODE_PROMPT_OVERRIDES)) {
    const node = nodes[id];
    if (node && typeof node.prompt === "string") node.prompt = prompt;
  }

  for (const [id, title] of Object.entries(NODE_TITLE_OVERRIDES)) {
    const node = nodes[id];
    if (node && typeof node.title === "string") node.title = title;
  }

  for (const node of Object.values(nodes)) {
    if (!Array.isArray(node.options)) continue;
    for (const option of node.options) {
      if (OPTION_LABEL_OVERRIDES[option.id]) {
        option.label = OPTION_LABEL_OVERRIDES[option.id];
      }
    }
  }

  for (const node of Object.values(nodes)) {
    if (typeof node.text === "string" && TEXT_REPLACEMENTS[node.text]) {
      node.text = TEXT_REPLACEMENTS[node.text];
    }
    if (typeof node.lesson === "string" && LESSON_REPLACEMENTS[node.lesson]) {
      node.lesson = LESSON_REPLACEMENTS[node.lesson];
    }
    for (const option of node.options ?? []) {
      if (typeof option.lesson === "string" && LESSON_REPLACEMENTS[option.lesson]) {
        option.lesson = LESSON_REPLACEMENTS[option.lesson];
      }
      if (typeof option.consequence === "string" && TEXT_REPLACEMENTS[option.consequence]) {
        option.consequence = TEXT_REPLACEMENTS[option.consequence];
      }
    }
  }

  const minigame = nodes["libreta-minigame"];
  if (minigame) {
    minigame.prompt = MINIGAME_PROMPT;
    for (const card of minigame.cards ?? []) {
      const override = MINIGAME_CARDS[card.id];
      if (!override) continue;
      Object.assign(card, override);
    }
  }

  const quiz = nodes["final-quiz"];
  if (quiz) {
    for (const question of quiz.questions ?? []) {
      const override = QUIZ_OVERRIDES[question.id];
      if (!override) continue;
      if (override.question) question.question = override.question;
      if (override.explanation) question.explanation = override.explanation;
      for (const option of question.options ?? []) {
        const optionOverride = override.options?.[option.id];
        if (optionOverride) Object.assign(option, optionOverride);
      }
    }
  }

  for (const id of ATMOSPHERIC_PAUSES) relinkAndRemove(nodes, id);

  return nodes;
}
